std::deque<int> data = {10, 20, 30, 40};
data.resize(100);

// O(1) Random Access: Index calculates (Block_Index, Offset)
int third = data[2];

// Use .at() for bounds checking (throws std::out_of_range)
try {
    data.at(99) = 5;
    data.at(100); // Out of bounds
} catch (const std::out_of_range& e) {
    // Access failed
}

// Random Access Iterator arithmetic is O(1)
auto it = data.begin();
it += 50; // Jumps 50 elements
*it = 99; // Sets data[50]
